class Employee {String empId,empName;double salary;boolean isIntern;Employee(String id,String name,double sal){empId=id;empName=name;salary=sal;isIntern=false;}Employee(String id,String name){this(id,name,0);isIntern=true;}void printProfile(){System.out.println(empId+" | "+empName+" | Rs "+salary+" | Intern: "+isIntern);}}
public class EmployeeProfileCreation {public static void main(String[] args){new Employee("E-101","Divya",65000).printProfile();new Employee("E-102","Arjun").printProfile();}}
